#!/bin/bash
set -eu
grep '^Cap' /proc/self/status >/out/actual-test-capabilities.txt
set +e
go test -race -count=1 -timeout=180s -json -run '^(TestResourceGuardDurableUnknownAndExplicitOriginalReplay|TestResourceGuardNewOwnerRetainsOriginalReadback|TestResourceGuardInFlightWriteKeepsCrossProcessFence|TestResourceGuardBoundsIdentityAndStrictPersistence|TestResourceGuardRejectsStateSymlinkAndPublicPermissions|TestResourceGuardMissingStateCannotResetFloor|TestResourceGuardProcIdentityParsing|TestBoundedBootstrapHoldsActualLimitsBeforePGBirth|TestBoundedBootstrapUnknownRequiresOriginalReadbackOrReplay|TestBoundedBootstrapRefusesExistingPGOrBareJournal|TestHeldRepairRestoresOnlyOriginalUpperAndKeepsSourceAcrossOwner|TestHeldRepairRejectsUnknownDriftAndChangedOriginalBeforeWrite|TestHeldRepairPartialFailureRetainsSameUpperAndRestartsExplicitly|TestHeldRepairBootstrapCannotAdoptUnrecordedProcess|TestHeldRepairPersistenceFailureCannotReachKernelWrite|TestHeldRepairKeepsFileLockAcrossKernelAndOwnerFence|TestHeldRepairNeverRepairsImmutableSystemPlacementOrLimits|TestNormalSplitTopologyOriginalPreparation|TestNormalSplitTopologyPendingReplayAndUnrecordedInode|TestNormalSplitTopologyRejectsSourceAndInitialHistory|TestNormalSplitTopologyCompletedDriftAndVariableArrays|TestNormalSplitTopologySerializesAndHonorsOriginalLock|TestNormalSplitTopologyMalformedJournalNoRepair|TestNormalSplitTopologyStrictPolicyAndFixedEntry|TestPrebootstrapSystemRecordsOnlyOriginalStageBeforeFullBudget|TestPrebootstrapSystemUnknownRequiresSameOriginalReplay|TestPrebootstrapSystemRejectsHistoryAndSourceDriftWithoutWrites|TestPrebootstrapSystemKeepsPendingOnEarlyMovableOrCorruptFiles|TestPrebootstrapSystemSerializesOriginalWALAndAllowsOnlyPostCompleteGrowth|TestPrebootstrapSystemProfileVersionsAndOriginalMarkers|TestPrebootstrapSystemSplitProfileSameOriginalRecovery|TestPrebootstrapSystemCompletedPGRequiresAppliedOriginalBootstrap|TestPrebootstrapSystemKernelAdaptersKeepEarlyCensusAndRecursiveEmpty)$' ./pkg/dsga/resourceguard >/out/test.json 2>/out/test.stderr
echo $? >/out/test.exitcode
